function applyCurrentSortOrder(list) {
  var sortValue = document.getElementById("sortEvidence").value;

  if (sortValue === "title-asc") {
    list.sort(function (a, b) {
      return a.title.localeCompare(b.title);
    });
  } else if (sortValue === "title-desc") {
    list.sort(function (a, b) {
      return b.title.localeCompare(a.title);
    });
  } else if (sortValue === "date-asc") {
    list.sort(function (a, b) {
      return new Date(a.timestamp) - new Date(b.timestamp);
    });
  } else {
    list.sort(function (a, b) {
      return new Date(b.timestamp) - new Date(a.timestamp);
    });
  }
  return list;
}

// The sort is now applied inside getFilteredEvidence, so this just needs to
// trigger a render — it survives filter/search renders too, not just this one.
export function handleSortChange() {
  renderEvidenceList();
}

